641	/// What every connection thread shares.
642	struct Shared {
643	    tls: Arc<ServerConfig>,
644	    requests: SyncSender<RemoteIncoming>,
645	    frames: SyncSender<SubscriberFrame>,
646	    wake: Arc<dyn Fn() + Send + Sync>,
647	    pools: Pools,
648	    limits: Limits,
649	    next_subscriber: AtomicU64,
650	}
651	
652	/// The TLS listener: an accept thread, one thread per connection,
653	/// requests handed to the frame over a bounded channel. Bound only by
654	/// the instance that holds the store lock.
655	pub struct RemotePort {
656	    addr: SocketAddr,
657	    requests: Receiver<RemoteIncoming>,
658	    frames: Receiver<SubscriberFrame>,
659	    stop: Arc<AtomicBool>,
660	    thread: Option<JoinHandle<()>>,
661	}
662	
663	impl RemotePort {
664	    /// Bind `addr` (port 0 picks one) with the host's TLS configuration.
665	    /// `wake` runs on a connection thread whenever a request is queued
666	    /// (an egui `request_repaint`).
667	    pub fn bind(
668	        addr: SocketAddr,
669	        tls: Arc<ServerConfig>,
670	        wake: impl Fn() + Send + Sync + 'static,
671	    ) -> io::Result<Self> {
672	        let listener = TcpListener::bind(addr)?;
673	        let addr = listener.local_addr()?;
674	        let (tx, requests) = mpsc::sync_channel(INBOX);
675	        let (frames_tx, frames) = mpsc::sync_channel(FRAMES);
676	        let stop = Arc::new(AtomicBool::new(false));
677	        let shared = Arc::new(Shared {
678	            tls,
679	            requests: tx,
680	            frames: frames_tx,
681	            wake: Arc::new(wake),
682	            pools: Pools::default(),
683	            limits: Limits {
684	                pair: Mutex::new(RateWindow::new(PAIR_PER_MINUTE, Duration::from_secs(60))),
685	                info: Mutex::new(RateWindow::new(INFO_PER_MINUTE, Duration::from_secs(60))),
686	            },
687	            next_subscriber: AtomicU64::new(1),
688	        });
689	        let thread = {
690	            let stop = Arc::clone(&stop);
691	            std::thread::Builder::new()
692	                .name("switchboard-remote".into())
693	                .spawn(move || {
694	                    for stream in listener.incoming() {
695	                        if stop.load(Ordering::SeqCst) {
696	                            break;
697	                        }
698	                        let Ok(stream) = stream else { continue };
699	                        // Past the pool a stranger is closed at once:
700	                        // dropping the stream is the close.
701	                        if shared.pools.unauthenticated.load(Ordering::SeqCst)
702	                            >= MAX_UNAUTHENTICATED
703	                        {
704	                            drop(stream);
705	                            continue;
706	                        }
707	                        shared.pools.unauthenticated.fetch_add(1, Ordering::SeqCst);
708	                        let shared = Arc::clone(&shared);
709	                        let _ = std::thread::Builder::new()
710	                            .name("switchboard-remote-conn".into())
711	                            .spawn(move || {
712	                                let paired = AtomicBool::new(false);
713	                                if let Err(e) = connection(stream, &shared, &paired) {
714	                                    log::debug!("remote connection: {e}");
715	                                }
716	                                if paired.load(Ordering::SeqCst) {
717	                                    shared.pools.paired.fetch_sub(1, Ordering::SeqCst);
718	                                } else {
719	                                    shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
720	                                }
721	                            });
722	                    }
723	                })?
724	        };
725	        Ok(Self {
726	            addr,
727	            requests,
728	            frames,
729	            stop,
730	            thread: Some(thread),
731	        })
732	    }
733	
734	    /// Up to `max` requests that arrived since the last poll, in
735	    /// arrival order; the rest wait on the channel.
736	    pub fn poll(&mut self, max: usize) -> Vec<RemoteIncoming> {
737	        self.requests.try_iter().take(max).collect()
738	    }
739	
740	    /// Every frame subscribed devices sent since the last poll.
741	    pub fn poll_frames(&mut self) -> Vec<SubscriberFrame> {
742	        self.frames.try_iter().collect()
743	    }
744	
745	    #[must_use]
746	    pub fn addr(&self) -> SocketAddr {
747	        self.addr
748	    }
749	}
750	
751	impl Drop for RemotePort {
752	    fn drop(&mut self) {
753	        self.stop.store(true, Ordering::SeqCst);
754	        // The accept loop only checks the flag after a connection, so
755	        // make one to unblock it.
756	        let unblock = if self.addr.ip().is_unspecified() {
757	            SocketAddr::new(IpAddr::from([127, 0, 0, 1]), self.addr.port())
758	        } else {
759	            self.addr
760	        };
761	        let _ = TcpStream::connect_timeout(&unblock, Duration::from_secs(1));
762	        if let Some(t) = self.thread.take() {
763	            let _ = t.join();
764	        }
765	    }
766	}
