/// What the frame answers: a status and a JSON body, and whether the
/// request was made by a paired device, which moves the connection
/// from the unauthenticated pool to the paired one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RemoteReply {
    pub status: u16,
    pub body: Vec<u8>,
    pub authenticated: bool,
}

input.new_string:
/// What the frame answers: a status and a JSON body, and whether the
/// request was made by a paired device, which moves the connection
/// from the unauthenticated pool to the paired one. `headers` are the
/// ones beyond the JSON defaults, such as the `Set-Cookie` of a pairing.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RemoteReply {
    pub status: u16,
    pub body: Vec<u8>,
    pub authenticated: bool,
    pub headers: Vec<(&'static str, String)>,
}

impl RemoteReply {
    #[must_use]
    pub fn new(status: u16, body: Vec<u8>, authenticated: bool) -> Self {
        Self {
            status,
            body,
            authenticated,
            headers: Vec::new(),
        }
    }
}

/// The name a host's session cookie carries: `__Host-sb-` and the
/// installation's id. Cookies ignore ports, so two instances on one
/// address share a cookie jar; the name keeps each to its own token.
/// The id survives a key rotation, so the cookie does too.
#[must_use]
pub fn cookie_name(server_id: Uuid) -> String {
    format!("__Host-sb-{server_id}")
}

/// The `Set-Cookie` that carries a pairing's token: `HttpOnly`, so the
/// page's script never holds it, `Secure`, `SameSite=Strict`, and
/// `__Host-` (no `Domain`, `Path=/`), for about 400 days.
#[must_use]
pub fn set_cookie(server_id: Uuid, token: &str) -> String {
    format!(
        "{}={token}; Max-Age=34560000; Path=/; Secure; HttpOnly; SameSite=Strict",
        cookie_name(server_id)
    )
}

/// The value of the cookie named `name` in a `Cookie` header, matched
/// by exact name; every other cookie is ignored.
#[must_use]
pub fn cookie_value<'a>(header: Option<&'a str>, name: &str) -> Option<&'a str> {
    header?
        .split(';')
        .filter_map(|pair| pair.trim().split_once('='))
        .find(|(n, _)| *n == name)
        .map(|(_, v)| v)
        .filter(|v| !v.is_empty())
}

