:root {
  color-scheme: light dark;
  --ink: #1d1d1f;
  --muted: #5f6368;
  --paper: #ffffff;
  --rule: #d0d3d8;
  --wait: #9a3412;
  --wait-bg: #fff1e8;
  --accent: #1d4ed8;
  font-family: -apple-system, system-ui, sans-serif;
  font-size: 17px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ink: #f2f2f4;
    --muted: #a7acb4;
    --paper: #1c1c1e;
    --rule: #3a3d43;
    --wait: #fdba74;
    --wait-bg: #3b2414;
    --accent: #93b4ff;
  }
}

body {
  margin: 0 auto;
  max-width: 40rem;
  padding: 1rem;
  color: var(--ink);
  background: var(--paper);
}

.top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 0.5rem;
}

h1 {
  font-size: 1.25rem;
  margin: 0;
}

h2 {
  font-size: 1.05rem;
  margin: 1.25rem 0 0.4rem;
}

.meta {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
}

.notice {
  margin: 0.75rem 0;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--rule);
  border-radius: 0.5rem;
}

.notice.warn {
  color: var(--wait);
  background: var(--wait-bg);
}

button,
.button {
  font: inherit;
  min-height: 2.75rem;
  padding: 0 1rem;
  border: 1px solid var(--accent);
  border-radius: 0.5rem;
  color: var(--accent);
  background: transparent;
}

button.primary {
  color: var(--paper);
  background: var(--accent);
}

button:disabled {
  opacity: 0.5;
}

textarea {
  font: inherit;
  box-sizing: border-box;
  width: 100%;
  min-height: 5rem;
  padding: 0.5rem;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 0.5rem;
