ul.rows {
  list-style: none;
  margin: 0;
  padding: 0;
}

ul.rows li {
  border-bottom: 1px solid var(--rule);
}

a.row {
  display: block;
  padding: 0.7rem 0;
  color: inherit;
  text-decoration: none;
}

a.row .name {
  font-weight: 600;
}

a.row .waiting {
  display: inline-block;
  margin-bottom: 0.2rem;
  padding: 0.05rem 0.45rem;
