/// The invite from the scanned or pasted text: the host's invite URL,
/// `https://<address>/#code=…&key=…&id=…`, or the JSON an earlier host
/// showed. The URL's fragment is what carries the code, so it is read
/// here and never sent anywhere.
public static func parse(_ text: String) throws -> PairingInvite {
    let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.hasPrefix("https://") else {
        return try Wire.decode(PairingInvite.self, from: Data(text.utf8))
    }
    let notAnInvite = DecodingError.dataCorrupted(
        .init(codingPath: [], debugDescription: "the text is not a pairing invite"))
    let rest = trimmed.dropFirst("https://".count)
    guard let hash = rest.firstIndex(of: "#") else { throw notAnInvite }
    let address = rest[..<hash].trimmingCharacters(in: CharacterSet(charactersIn: "/"))
    var values: [String: String] = [:]
    for pair in rest[rest.index(after: hash)...].split(separator: "&") {
        let parts = pair.split(separator: "=", maxSplits: 1).map(String.init)
        if parts.count == 2 { values[parts[0]] = parts[1] }
    }
    guard let code = values["code"], !code.isEmpty,
        let key = values["key"], let id = values["id"]
    else { throw notAnInvite }
    return PairingInvite(
        serverID: ServerID(id), spkiSha256: key, code: code, addresses: [address])
}

