/// Open the window and pair as a browser does: the token comes back as a
/// cookie named for the host, and the body carries none. Returns the
/// device's id, the cookie's name and its token.
fn pair_cookie(port: &mut Port, code: &str, scope: Scope, name: &str) -> (String, String, String) {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let identity = port.remote.state().identity.clone().unwrap();
    let body = serde_json::json!({
        "code": code,
        "spki_sha256": identity.spki_sha256,
        "device_name": name,
        "transport": "cookie",
    });
    let (head, reply) = call_with(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(head.status, 200, "{reply}");
    let cookie = remote::cookie_name(identity.server_id);
    let set = head.header("set-cookie").expect("a Set-Cookie");
    let token = set
        .split(';')
        .next()
        .and_then(|pair| pair.strip_prefix(&format!("{cookie}=")))
        .expect("the cookie is named for this host")
        .to_owned();
    let device = reply["body"]["device_id"].as_str().unwrap().to_owned();
    (device, cookie, token)
}

/// The Content-Security-Policy the page's replies carry, exactly.
const PAGE_CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";

/// The three page files answer to anyone, with their type and the policy;
/// anything else outside the API is the frame's JSON refusal.
#[test]
fn the_page_files_answer_before_pairing_with_their_policy() {
    let mut port = port();
    let pages = [
        ("/", include_str!("../web/index.html"), "text/html; charset=utf-8"),
        ("/app.js", include_str!("../web/app.js"), "text/javascript; charset=utf-8"),
        ("/app.css", include_str!("../web/app.css"), "text/css; charset=utf-8"),
    ];
    for (path, body, content_type) in pages {
        let head = exchange(port.addr, &port.client, "GET", path, &[], "").expect("page");
        assert_eq!(head.status, 200, "{path}");
        assert_eq!(head.header("content-type"), Some(content_type), "{path}");
        assert_eq!(head.header("content-security-policy"), Some(PAGE_CSP), "{path}");
        assert_eq!(head.header("cache-control"), Some("no-store"), "{path}");
        assert_eq!(head.header("x-content-type-options"), Some("nosniff"), "{path}");
        assert_eq!(head.header("referrer-policy"), Some("no-referrer"), "{path}");
        assert_eq!(head.header("connection"), Some("close"), "{path}");
        assert_eq!(head.body, body, "{path}");
    }
    // A query is ignored and never echoed.
    let head = exchange(port.addr, &port.client, "GET", "/?code=ABCD2345", &[], "").unwrap();
    assert_eq!(head.body, include_str!("../web/index.html"));

    for (method, path) in [("GET", "/favicon.ico"), ("GET", "/api"), ("POST", "/")] {
        let (status, reply) = call(&mut port, method, path, None, "");
        assert_eq!((status, code(&reply)), (404, "not_found"), "{method} {path}: {reply}");
    }
}

/// The page names only what the host serves, and its markup and script
/// stay inside the policy: no inline script, style or handler, no markup
/// written from a string. Every API path the script names answers for a
/// paired device, something other than `not_found`.
#[test]
fn the_page_names_only_what_the_host_serves_and_keeps_its_markup_plain() {
    let html = include_str!("../web/index.html");
    let script = include_str!("../web/app.js");
    for attr in ["src=\"", "href=\""] {
        for (at, _) in html.match_indices(attr) {
            let value = &html[at + attr.len()..];
            let value = &value[..value.find('"').unwrap()];
            assert!(
                ["/", "/app.js", "/app.css"].contains(&value) || value.starts_with("data:"),
                "{value} is not served"
            );
        }
    }
    for (at, _) in html.match_indices("<script") {
        let tag = &html[at..at + html[at..].find('>').unwrap()];
        assert!(tag.contains("src="), "an inline script: {tag}");
    }
    assert!(!html.contains("style="), "no inline style");
    assert!(
        !html.split_whitespace().any(|w| w.starts_with("on") && w.contains('=')),
        "no inline handler"
    );
    for banned in ["innerHTML", "outerHTML", "eval(", "document.write", "insertAdjacentHTML"] {
        assert!(!script.contains(banned), "the script uses {banned}");
    }

    let (_, _, session) = seed(&mut port, "");
    let (_, project_id, _) = (
        (),
        port.app
            .core()
            .projects()
            .first()
            .map(|p| p.id.0.to_string())
            .unwrap(),
        (),
    );
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Vision Pro");
    let mut checked = 0;
    for (at, _) in script.match_indices("\"/api/v1/") {
        let rest = &script[at + 1..];
        let path = &rest[..rest.find('"').unwrap()];
        let path = if path.contains("projects/{id}") {
            path.replace("{id}", &project_id)
        } else {
            path.replace("{id}", &session)
        };
        let (method, bearer) = match path.as_str() {
            "/api/v1/pair" => ("POST", None),
            p if p.ends_with("/send") => ("POST", Some(token.as_str())),
            _ => ("GET", Some(token.as_str())),
        };
        let (status, reply) = call(&mut port, method, &path, bearer, "{}");
        assert_ne!(code(&reply), "not_found", "{method} {path}: {status} {reply}");
        checked += 1;
    }
    assert!(checked >= 10, "the script names its routes: {checked}");
}

/// A browser pairs as the page does: the cookie is `HttpOnly`, `Secure`,
/// `SameSite=Strict`, `__Host-` and named for the host, and the body holds
/// no token. The cookie alone reads `/me`. A native pair is unchanged.
#[test]
fn a_browser_pairs_with_a_cookie_and_no_token_in_the_body() {
    let mut port = port();
    let identity = port.remote.state().identity.clone().unwrap();
    port.app.dispatch(AppAction::OpenPairing {
        code: "ABCD2345".into(),
        scope: Scope::Read,
    });
    let body = serde_json::json!({
        "code": "ABCD2345",
        "spki_sha256": identity.spki_sha256,
        "device_name": "Safari on iPhone",
        "transport": "cookie",
    });
    let (head, reply) = call_with(&mut port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(head.status, 200, "{reply}");
    let name = format!("__Host-sb-{}", identity.server_id);
    let set = head.header("set-cookie").expect("a Set-Cookie");
    let (pair, attrs) = set.split_once("; ").unwrap();
    assert!(pair.starts_with(&format!("{name}=")), "{set}");
    for attr in ["Max-Age=34560000", "Path=/", "Secure", "HttpOnly", "SameSite=Strict"] {
        assert!(attrs.split("; ").any(|a| a == attr), "{attr} in {set}");
    }
    assert!(!set.contains("Domain"), "{set}");
    assert!(reply["body"]["token"].is_null(), "no token in the body");
    assert_eq!(reply["body"]["server_id"], identity.server_id.to_string());

    let cookie = format!("{}={}", name, &pair[name.len() + 1..]);
    let (head, me) = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(head.status, 200, "{me}");
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["server_name"], identity.server_name);

    let (head, native) = call_with(
        &mut port,
        "POST",
        "/api/v1/pair",
        &[],
        &serde_json::json!({"code": "AAAA2345", "spki_sha256": identity.spki_sha256}).to_string(),
    );
    assert_eq!(head.status, 403, "the window is closed after a pairing");
    assert_eq!(code(&native), "pairing_closed");
    let _ = pair_cookie(&mut port, "AAAA2345", Scope::Read, "Vision Pro");
    port.app.dispatch(AppAction::OpenPairing {
        code: "BBBB2345".into(),
        scope: Scope::Read,
    });
    let (head, native) = call_with(
        &mut port,
        "POST",
        "/api/v1/pair",
        &[],
        &serde_json::json!({"code": "BBBB2345", "spki_sha256": identity.spki_sha256, "device_name": "Vision Pro"})
            .to_string(),
    );
    assert_eq!(head.status, 200, "{native}");
    assert!(head.header("set-cookie").is_none(), "a native pair gets no cookie");
    assert!(native["body"]["token"].is_string(), "its token is in the body");
}

/// Two instances on one address: each host's cookie is its own name, a
/// host reads only its own, and a cookie under the fixed name reads nothing.
#[test]
fn two_hosts_on_one_address_never_read_each_others_cookie() {
    let mut a = port();
    let mut b = port();
    let (device_a, name_a, token_a) = pair_cookie(&mut a, "ABCD2345", Scope::Read, "Pad");
    let (_, name_b, token_b) = pair_cookie(&mut b, "ABCD2345", Scope::Read, "Pad");
    assert_ne!(name_a, name_b, "each host names its cookie for its own id");

    let only_b = format!("{name_b}={token_b}");
    let (head, _) = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &only_b)], "");
    assert_eq!(head.status, 401, "another host's cookie is not this host's");

    let both = format!("{only_b}; {name_a}={token_a}");
    let (head, me) = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &both)], "");
    assert_eq!(head.status, 200, "{me}");
    assert_eq!(me["body"]["device_id"], device_a, "a's own device");

    let fixed = format!("__Host-sb={token_a}");
    let (head, _) = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &fixed)], "");
    assert_eq!(head.status, 401, "the fixed name authenticates nothing");
}

/// A cookie is a credential the browser sends on its own, so a write from
/// it must come from this host's own origin; a bearer, a read, and a write
/// from the right origin are not refused for the origin.
#[test]
fn a_write_by_cookie_must_come_from_this_hosts_own_origin() {
    let mut port = port();
    let (_, session) = {
        let (_, _, session) = seed(&mut port, "");
        ((), session)
    };
    let (_, name, token) = pair_cookie(&mut port, "ABCD2345", Scope::Control, "Pad");
    let cookie = format!("{name}={token}");
    let path = format!("/api/v1/sessions/{session}/send");
    let body = r#"{"op":"o1","text":"hi"}"#;

    let (head, reply) = call_with(&mut port, "POST", &path, &[("Cookie", &cookie)], body);
    assert_eq!((head.status, code(&reply)), (403, "origin"), "{reply}");
    let (head, reply) = call_with(
        &mut port,
        "POST",
        &path,
        &[("Cookie", &cookie), ("Origin", "https://evil.example")],
        body,
    );
    assert_eq!((head.status, code(&reply)), (403, "origin"), "{reply}");
    let (head, reply) = call_with(
        &mut port,
        "POST",
        &path,
        &[("Cookie", &cookie), ("Origin", "https://localhost")],
        body,
    );
    assert_ne!(code(&reply), "origin", "{reply}");
    assert_ne!(head.status, 403, "{reply}");

    let bearer = pair(&mut port, "BBBB2345", Scope::Control, "Vision Pro");
    let (_, reply) = call(&mut port, "POST", &path, Some(&bearer), body);
    assert_ne!(code(&reply), "origin", "a bearer is exempt: {reply}");
    let (head, _) = call_with(&mut port, "GET", "/api/v1/waiting", &[("Cookie", &cookie)], "");
    assert_eq!(head.status, 200, "a read by cookie needs no origin");
}

/// `/me` says the scope the device has now, and follows a change of it.
#[test]
fn me_reports_the_scope_the_device_has_now() {
    let mut port = port();
