        scope: Scope::Control,
    });
    let (_, me) = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(me["body"]["scope"], "control");
}

/// After a revocation the cookie is the same 401 an unknown token is, and
/// `/info` still names the same host and key, which is what lets the page
/// say the device was removed.
#[test]
fn a_revoked_cookie_is_unauthorized_and_info_names_the_same_host() {
    let mut port = port();
    let (_, before) = get(&mut port, "/api/v1/info", None);
    let (device, name, token) = pair_cookie(&mut port, "ABCD2345", Scope::Read, "Pad");
    port.app.dispatch(AppAction::RevokeDevice(
        uuid::Uuid::parse_str(&device).unwrap(),
    ));
    let cookie = format!("{name}={token}");
    let (head, reply) = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(
        (head.status, code(&reply)),
        (401, "unauthorized"),
        "{reply}"
    );
    let (_, after) = get(&mut port, "/api/v1/info", None);
    assert_eq!(after["body"]["server_id"], before["body"]["server_id"]);
    assert_eq!(after["body"]["spki_sha256"], before["body"]["spki_sha256"]);
}

/// A page load is an unauthenticated connection that closes after its
/// reply, so four sequential loads leave the pool as it was.
#[test]
fn a_page_load_frees_its_slot_at_once() {
    let port = port();
    for _ in 0..(MAX_UNAUTHENTICATED + 1) {
        let head = exchange(port.addr, &port.client, "GET", "/app.css", &[], "").expect("page");
        assert_eq!(head.status, 200);
        // The listener's thread frees the slot just after the close.
        std::thread::sleep(Duration::from_millis(50));
    }
}

/// Pages have their own window: 120 a minute, and the 121st is 429 while
/// `/info` (its own window) still answers.
#[test]
fn page_loads_are_limited_per_minute_on_their_own_window() {
    let mut port = port();
    for n in 0..120 {
        let head = exchange(port.addr, &port.client, "GET", "/", &[], "").expect("page");
        assert_eq!(head.status, 200, "load {n}");
    }
    let head = exchange(port.addr, &port.client, "GET", "/", &[], "").expect("page");
    assert_eq!(head.status, 429, "the 121st load in a minute");
    let (status, _) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200, "the info window is its own");
}

/// The page's own logic under node's test runner. Skipped where node is
/// absent, as the tmux tests are skipped where tmux is.
#[test]
fn the_page_logic_passes_its_node_tests() {
    let node = std::process::Command::new("node").arg("--version").output();
    if !node.is_ok_and(|o| o.status.success()) {
        eprintln!("node is not installed: the page's tests are skipped");
        return;
    }
    let script = concat!(env!("CARGO_MANIFEST_DIR"), "/web/app.test.js");
    let status = std::process::Command::new("node")
        .args(["--test", script])
        .status()
        .expect("node runs");
    assert!(status.success(), "the page's node tests failed");
}

