#[test]
fn a_request_reads_its_cookie_origin_and_host_and_a_cookie_is_matched_by_name() {
    let text = b"POST /api/v1/x HTTP/1.1\r\nHost: 192.168.1.9:43187\r\nOrigin: https://192.168.1.9:43187\r\nCookie: a=1; __Host-sb-x=tok\r\nContent-Length: 0\r\n\r\n";
    let mut r = BufReader::new(&text[..]);
    let req = read_request(&mut r).unwrap().unwrap();
    assert_eq!(req.host.as_deref(), Some("192.168.1.9:43187"));
    assert_eq!(req.origin.as_deref(), Some("https://192.168.1.9:43187"));
    assert_eq!(req.bearer, None);
    let id = Uuid::nil();
    assert_eq!(
        cookie_name(id),
        "__Host-sb-00000000-0000-0000-0000-000000000000"
    );
    let name = "__Host-sb-x";
    assert_eq!(cookie_value(req.cookie.as_deref(), name), Some("tok"));
    assert_eq!(cookie_value(req.cookie.as_deref(), "__Host-sb"), None);
    assert_eq!(cookie_value(None, name), None);
    assert_eq!(cookie_value(Some("__Host-sb-xx=1"), name), None);
    assert_eq!(cookie_value(Some("__Host-sb-x="), name), None, "empty");
}

#[test]
fn a_set_cookie_carries_the_host_flags_and_the_token() {
    let id = Uuid::new_v4();
    let set = set_cookie(id, "tok");
    assert_eq!(
        set,
        format!(
            "__Host-sb-{id}=tok; Max-Age=34560000; Path=/; Secure; HttpOnly; SameSite=Strict"
        )
    );
}

#[test]
fn a_json_reply_carries_its_headers_and_the_defaults() {
    let mut reply = RemoteReply::new(200, b"{}".to_vec(), true);
    reply.headers.push(("Set-Cookie", "c=1".into()));
    let mut out = Vec::new();
    respond(&mut out, &reply).unwrap();
    let text = String::from_utf8(out).unwrap();
    assert!(text.starts_with("HTTP/1.1 200 OK\r\n"), "{text}");
    assert!(text.contains("\r\nCache-Control: no-store\r\n"), "{text}");
    assert!(text.contains("\r\nX-Content-Type-Options: nosniff\r\n"), "{text}");
    assert!(text.contains("\r\nSet-Cookie: c=1\r\n"), "{text}");
    assert!(text.ends_with("\r\n\r\n{}"), "{text}");
}

