fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let token = match &request.bearer {
        Some(token) => token.clone(),
        None => {
            let server_id = self.core.identity().map(|i| i.server_id);
            let cookie = server_id.and_then(|id| {
                let name = remote::cookie_name(id);
                remote::cookie_value(request.cookie.as_deref(), &name).map(str::to_owned)
            });
            let Some(token) = cookie else {
                return Err(self.refuse(
                    request,
                    401,
                    "unauthorized",
                    "pair this device first",
                    false,
                ));
            };
            let writes = request.method != "GET" || request.upgrade.is_some();
            let same_origin = request.host.as_deref().is_some_and(|host| {
                request.origin.as_deref() == Some(&format!("https://{host}"))
            });
            if writes && !same_origin {
                return Err(self.refuse(
                    request,
                    403,
                    "origin",
                    "a write from a browser must come from this host's own page",
                    false,
                ));
            }
            token
        }
    };
    let Some(device) = self
        .core
        .device_by_token(&remote::token_sha256(&token))
        .cloned()
    else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "the token is not known; pair again",
            false,
        ));
    };
    self.dispatch_inner(AppAction::DeviceSeen(device.id));
    Ok(device)
}

